// --- M1-20 -------------------------------------------------------------------------------------
const answerOf = (
  input: Record<string, unknown>,
  vhosts: Record<string, FakeVhost>,
) =>
  runQuery(topologySubgraph, createTopologySubgraphAction, input, { vhosts });

/** A fanout exchange with `queues` queues bound to it, other exchanges bound to some of them. */
function wideVhost(queues: number, exchanges: number, extraBindings: number) {
  const queueNames = Array.from(
    { length: queues },
    (_, i) => `q-${String(i).padStart(4, '0')}`,
  );
  const others = Array.from(
    { length: exchanges - 1 },
    (_, i) => `ex-${String(i).padStart(2, '0')}`,
  );
  return {
    exchanges: [
      { name: 'fan', type: 'fanout' },
      ...others.map((name) => ({ name })),
    ],
    queues: queueNames.map((name) => ({
      name,
      type: 'classic',
      policy: null,
      operator_policy: null,
    })),
    bindings: [
      ...queueNames.map((destination) => ({ source: 'fan', destination })),
      ...Array.from({ length: extraBindings }, (_, i) => ({
        source: others[i % others.length] ?? 'fan',
        destination: queueNames[(i * 7) % queues] ?? 'q-0000',
        routing_key: `k${String(i)}`,
      })),
    ],
  } satisfies FakeVhost;
}

describe('M1-20 AC-1 subgraph of a 5k element vhost is capped and aggregated', () => {
  const vhost = wideVhost(1_800, 100, 1_300);
  const input = {
    vhost: '/',
    focus: { kind: 'exchange', name: 'fan' },
    depth: 2,
  };

  it('returns at most 2,000 elements with the aggregation marker and the exact totals', async () => {
    const { output } = await answerOf(input, { '/': vhost });
    const { graph } = output;

    // The vhost has 1,900 objects and 3,100 bindings: about 5,000 elements.
    expect(graph.totals).toEqual({
      exchanges: 100,
      queues: 1_800,
      bindings: 3_100,
      links: 0,
      unrepresented: 0,
    });
    expect(graph.elements).toBeLessThanOrEqual(2_000);
    expect(graph.elements).toBe(graph.nodes.length + graph.edges.length);
    expect(graph.aggregated).toBe(true);
    expect(graph.nodes.some((n) => n.id === 'x:fan')).toBe(true);
    const aggregate = graph.nodes.find(
      (n) => n.kind === 'aggregate' && n.of === 'queue',
    );
    expect(aggregate).toMatchObject({ of: 'queue', via: 'x:fan' });
    expect(aggregate?.kind === 'aggregate' && aggregate.count).toBeGreaterThan(
      100,
    );
    // What the scope held is accounted for: shown one by one, or folded.
    const shown = graph.nodes.filter((n) => n.kind !== 'aggregate').length;
    const folded = graph.nodes.reduce(
      (sum, n) => sum + (n.kind === 'aggregate' ? n.count : 0),
      0,
    );
    expect(shown + folded).toBe(graph.scope.nodes);
    expect(graph.omitted.nodes).toBe(folded);
    expect(output.gaps).toEqual([]);
  });

  it('answers the same call twice with the same graph', async () => {
    const first = await answerOf(input, { '/': vhost });
    const second = await answerOf(input, { '/': vhost });

    expect(second.output).toEqual(first.output);
  });

  it('honours a smaller cap asked for', async () => {
    const { output } = await answerOf(
      { ...input, maxElements: 100 },
      { '/': vhost },
    );

    expect(output.graph.elements).toBeLessThanOrEqual(100);
    expect(output.graph.nodes.some((n) => n.id === 'x:fan')).toBe(true);
  });

  it('refuses a cap past the ceiling of the contract', async () => {
    await expect(
      answerOf({ ...input, maxElements: 2_001 }, { '/': vhost }),
    ).rejects.toMatchObject({ code: 'VALIDATION_FAILED' });
  });
});

describe('M1-20 AC-3 subgraph depth is at most 2 and the focus must exist', () => {
  const vhost: FakeVhost = {
    exchanges: [{ name: 'a' }, { name: 'b' }, { name: 'c' }, { name: 'd' }],
    queues: [{ name: 'qd', policy: null, operator_policy: null }],
    bindings: [
      { source: 'a', destination: 'b', destination_type: 'exchange' },
      { source: 'b', destination: 'c', destination_type: 'exchange' },
      { source: 'c', destination: 'd', destination_type: 'exchange' },
      { source: 'd', destination: 'qd' },
    ],
  };
  const around = (depth?: number, name = 'b') =>
    answerOf(
      {
        vhost: '/',
        focus: { kind: 'exchange', name },
        ...(depth === undefined ? {} : { depth }),
      },
      { '/': vhost },
    );
  const idsOf = async (depth?: number) =>
    (await around(depth)).output.graph.nodes.map((n) => n.id);

  it('shows the focus at depth 0, one hop by default and at 1, two hops at 2', async () => {
    expect(await idsOf(0)).toEqual(['x:b']);
    expect(await idsOf()).toEqual(['x:a', 'x:b', 'x:c']);
    expect(await idsOf(1)).toEqual(['x:a', 'x:b', 'x:c']);
    expect(await idsOf(2)).toEqual(['x:a', 'x:b', 'x:c', 'x:d']);
  });

  it('refuses a depth of 3 as an invalid request', async () => {
    await expect(around(3)).rejects.toMatchObject({
      code: 'VALIDATION_FAILED',
    });
  });

  it('says an exchange the vhost does not have is not found', async () => {
    await expect(around(1, 'nope')).rejects.toMatchObject({
      code: 'NOT_FOUND',
    });
  });

  it('reports what lies beyond the answer, so a client can ask for it', async () => {
    const { output } = await around(1);
    const edge = output.graph.nodes.find((n) => n.id === 'x:c');

    expect(edge).toMatchObject({ hasMore: true });
    expect(output.graph.focus).toEqual({ kind: 'exchange', name: 'b' });
    expect(output.graph.depth).toBe(1);
  });
});
